"""Class 6 Maths Ch 8 - Playing with Constructions."""
from g67 import *

SLUG, NAME, CHNO = "Playing_with_Constructions", "Playing with Constructions", 8

def rel(r1, r2, d):
    if d > r1 + r2: return "do not touch (separate)"
    if d == r1 + r2: return "touch externally"
    if d == abs(r1 - r2): return "touch internally"
    if d < abs(r1 - r2): return "one lies inside the other"
    return "intersect at two points"
RELS = ["do not touch (separate)", "touch externally", "touch internally", "one lies inside the other", "intersect at two points"]
def relq(r1, r2, d):
    c = rel(r1, r2, d); return tm(f"Two circles have radii {r1} cm and {r2} cm and their centres are {d} cm apart. The circles:", c, [x for x in RELS if x != c][:3], f"Compare {d} with {r1}+{r2}={r1+r2} and |{r1}-{r2}|={abs(r1-r2)}.")
def tc(q, a, w, why="Property"): return tm(q, a, w, why)
def tmq(items): return [tc(q, a, w) for q, a, w in items]

